    public static string Get(string iconName, int size = 16)
    {
        if (Icons.TryGetValue(iconName, out var template))
        {
            return string.Format(template, size);
        }

        var clean = iconName.ToLowerInvariant().Replace("-", "").Replace("_", "");
        foreach (var kvp in Icons)
        {
            if (kvp.Key.Replace("-", "").Replace("_", "").Equals(clean, StringComparison.OrdinalIgnoreCase))
            {
                return string.Format(kvp.Value, size);
            }
        }

        return string.Empty;
    }
